CREATE TABLE IF NOT EXISTS public.dhis2_tb_surveillance (
    record_id VARCHAR(160) PRIMARY KEY, -- upi || '_' || enrollment_id
    upi VARCHAR(128) NOT NULL, -- Unique ID (UPI)
    tracked_entity_instance VARCHAR(64),
    enrollment_id VARCHAR(64),
    program_id VARCHAR(64) DEFAULT 'Lt6P15ps7f6',
